negative_controls.command:
python3 -c "import sys; from scripts.runtime import pr_merge_control as p; result = None; error = False;
try:
 c = p.load_ci_truth_contract(p.DEFAULT_CI_TRUTH_CONTRACT); rollup = [{'name': e['names'][0], 'status': 'COMPLETED', 'conclusion': 'SUCCESS'} for e in c['required']]; rollup.append({'name': 'AgentOps packet scope', 'status': 'COMPLETED', 'conclusion': 'FAILURE'}); result = p.classify_pr({'number': 1, 'title': 'negative control', 'isDraft': False, 'mergeable': 'MERGEABLE', 'reviewDecision': 'APPROVED', 'statusCheckRollup': rollup})
except Exception:
 error = True
sys.exit(3 if error else (1 if result['status'] == 'GITHUB_GREEN_NEEDS_PACKET' and result['checks']['failing'] == ['AgentOps packet scope'] else 0))"
